package com.nm.fragmentsclean.experienceContext.write.businesslogic.usecases;
import com.nm.fragmentsclean.experienceContext.write.businesslogic.gateways.ExperienceMediaRepository;import com.nm.fragmentsclean.sharedKernel.businesslogic.models.*;import jakarta.transaction.Transactional;import java.util.UUID;
public class CompleteExperienceMediaDeletion{private final ExperienceMediaRepository media;private final DomainEventPublisher events;private final DateTimeProvider clock;public CompleteExperienceMediaDeletion(ExperienceMediaRepository media,DomainEventPublisher events,DateTimeProvider clock){this.media=media;this.events=events;this.clock=clock;}@Transactional public void complete(UUID mediaId){var item=media.byId(mediaId).orElse(null);if(item==null)return;var now=clock.now();if(item.snapshot().status()==com.nm.fragmentsclean.experienceContext.write.businesslogic.models.ExperienceMediaStatus.PENDING)item.requestDeletion(now);if(!item.markDeleted(now))return;media.save(item);item.registerChanged(UUID.randomUUID(),"OBJECTS_DELETED",null,now);ExperienceEvents.publish(item,events);}}
